#!/usr/bin/env python3
# Converts the design SVG drawings (generated by gen-svg.mjs) into WPF XAML ResourceDictionaries of
# frozen DrawingImage objects, so the drawings stay sharp at every size (no flat bitmaps).
# Supported subset (all the design uses): g, path, rect, circle, ellipse, text (to outlines), nested svg,
# linear/radial gradients (objectBoundingBox), clipPath, transform (translate/rotate/scale/matrix),
# opacity, fill/stroke (+opacity), stroke-width/linecap/linejoin. Anything else raises an error.
# Usage: python3 svg2xaml.py <svgDir> <fontWoff2> <outDir>
import math, re, sys, os, glob
from xml.sax.saxutils import quoteattr
from lxml import etree
from fontTools.ttLib import TTFont
from fontTools.pens.svgPathPen import SVGPathPen
from fontTools.pens.transformPen import TransformPen

SVGNS = '{http://www.w3.org/2000/svg}'

def fmt(v):
    s = ('%.3f' % v).rstrip('0').rstrip('.')
    return '0' if s in ('-0', '') else s

# ---------- matrices ----------
def mul(a, b):  # a then b?  we use column vectors: result = a * b (apply b first)
    return (a[0]*b[0] + a[2]*b[1], a[1]*b[0] + a[3]*b[1],
            a[0]*b[2] + a[2]*b[3], a[1]*b[2] + a[3]*b[3],
            a[0]*b[4] + a[2]*b[5] + a[4], a[1]*b[4] + a[3]*b[5] + a[5])
I = (1, 0, 0, 1, 0, 0)

def parse_transform(t):
    m = I
    if not t:
        return m
    for name, args in re.findall(r'(\w+)\s*\(([^)]*)\)', t):
        a = [float(x) for x in re.split(r'[\s,]+', args.strip()) if x]
        if name == 'translate':
            mm = (1, 0, 0, 1, a[0], a[1] if len(a) > 1 else 0)
        elif name == 'scale':
            mm = (a[0], 0, 0, a[1] if len(a) > 1 else a[0], 0, 0)
        elif name == 'rotate':
            r = math.radians(a[0]); c, s = math.cos(r), math.sin(r)
            mm = (c, s, -s, c, 0, 0)
            if len(a) == 3:
                mm = mul(mul((1, 0, 0, 1, a[1], a[2]), mm), (1, 0, 0, 1, -a[1], -a[2]))
        elif name == 'matrix':
            mm = tuple(a)
        else:
            raise ValueError('transform ' + name)
        m = mul(m, mm)
    return m

def matrix_xaml(m):
    return ','.join(fmt(x) for x in m)

# ---------- colors ----------
NAMED = {'none': None, 'white': (255, 255, 255), 'black': (0, 0, 0)}
def parse_color(c):
    c = c.strip()
    if c.lower() in NAMED:
        v = NAMED[c.lower()]
        return None if v is None else (v, 1.0)
    if c.startswith('#'):
        h = c[1:]
        if len(h) == 3:
            h = ''.join(ch * 2 for ch in h)
        return ((int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)), 1.0)
    m = re.match(r'rgba?\(([^)]*)\)', c)
    if m:
        p = [x.strip() for x in m.group(1).split(',')]
        return ((int(float(p[0])), int(float(p[1])), int(float(p[2]))), float(p[3]) if len(p) > 3 else 1.0)
    raise ValueError('color ' + c)

def argb(rgb, alpha):
    a = max(0, min(255, round(alpha * 255)))
    return '#%02X%02X%02X%02X' % (a, rgb[0], rgb[1], rgb[2])

# ---------- path data ----------
NUM = r'[-+]?(?:\d*\.\d+|\d+\.?)(?:[eE][-+]?\d+)?'
def normalize_path(d):
    """Re-prints SVG path data with explicit separators (arc flags may be glued in SVG).
    NO "F1" prefix: PathGeometry.Figures uses PathFigureCollection.Parse, whose parser rejects "F" (FormatException at
    load time = "Provide value on TypeConverterMarkupExtension threw an exception"). The fill rule (SVG = nonzero,
    WPF default = EvenOdd) is set with the FillRule attribute, see Conv.geometry."""
    out, pos, cmd, argi = [], 0, None, 0
    ws = re.compile(r'[\s,]*')
    num = re.compile(NUM)
    while True:
        pos = ws.match(d, pos).end()
        if pos >= len(d):
            break
        ch = d[pos]
        if ch.isalpha():
            cmd, argi = ch, 0
            out.append(ch); pos += 1
            continue
        if cmd in ('A', 'a') and argi % 7 in (3, 4):
            if ch not in '01':
                raise ValueError('bad arc flag in ' + d[:60])
            out.append(ch); pos += 1; argi += 1
            continue
        m = num.match(d, pos)
        if not m:
            raise ValueError('bad path data near: ' + d[pos:pos + 20])
        out.append(fmt(float(m.group(0)))); pos = m.end(); argi += 1
    return ' '.join(out)

# ---------- text to outlines ----------
class Glyphs:
    def __init__(self, font_path):
        self.font = TTFont(font_path)
        self.gs = self.font.getGlyphSet()
        self.cmap = self.font.getBestCmap()
        self.upm = self.font['head'].unitsPerEm
    def path(self, text, x, y, size, anchor):
        s = size / self.upm
        width = sum(self.gs[self.cmap[ord(ch)]].width for ch in text) * s
        cx = x - (width / 2 if anchor == 'middle' else width if anchor == 'end' else 0)
        parts = []
        for ch in text:
            g = self.gs[self.cmap[ord(ch)]]
            pen = SVGPathPen(self.gs)
            g.draw(TransformPen(pen, (s, 0, 0, -s, cx, y)))
            parts.append(pen.getCommands())
            cx += g.width * s
        return normalize_path(' '.join(parts))

# ---------- converter ----------
class Conv:
    def __init__(self, key, glyphs):
        self.key, self.glyphs = key, glyphs
        self.brushes, self.brush_xaml, self.clips = {}, [], {}
        self.grads = {}

    def collect_defs(self, root):
        for el in root.iter(SVGNS + 'linearGradient', SVGNS + 'radialGradient'):
            self.grads[el.get('id')] = el
        for el in root.iter(SVGNS + 'clipPath'):
            self.clips[el.get('id')] = el

    def brush(self, ref, opacity=1.0):
        gid = re.match(r'url\(#([^)]+)\)', ref).group(1)
        k = (gid, round(opacity, 3))
        if k in self.brushes:
            return self.brushes[k]
        el = self.grads[gid]
        name = '%s.%s%s' % (self.key, gid, '' if opacity == 1 else '.o' + fmt(opacity).replace('.', '_'))
        stops = []
        for st in el.iter(SVGNS + 'stop'):
            rgb, a = parse_color(st.get('stop-color'))
            a *= float(st.get('stop-opacity', '1')) * opacity
            stops.append('<GradientStop Color="%s" Offset="%s"/>' % (argb(rgb, a), fmt(float(st.get('offset')))))
        tag = etree.QName(el).localname
        if tag == 'linearGradient':
            head = '<LinearGradientBrush x:Key=%s StartPoint="%s,%s" EndPoint="%s,%s" po:Freeze="True">' % (
                quoteattr(name), el.get('x1', '0'), el.get('y1', '0'), el.get('x2', '1'), el.get('y2', '0'))
            tail = '</LinearGradientBrush>'
        else:
            cx, cy, r = el.get('cx', '.5'), el.get('cy', '.5'), el.get('r', '.5')
            fx, fy = el.get('fx', cx), el.get('fy', cy)
            head = '<RadialGradientBrush x:Key=%s Center="%s,%s" RadiusX="%s" RadiusY="%s" GradientOrigin="%s,%s" po:Freeze="True">' % (
                quoteattr(name), cx, cy, r, r, fx, fy)
            tail = '</RadialGradientBrush>'
        self.brush_xaml.append(head + ''.join(stops) + tail)
        self.brushes[k] = '{StaticResource %s}' % name
        return self.brushes[k]

    def paint(self, value, opacity):
        if value is None or value == 'none':
            return None
        if value.startswith('url('):
            return self.brush(value, opacity)
        c = parse_color(value)
        if c is None:
            return None
        return argb(c[0], c[1] * opacity)

    def geometry(self, el, style):
        tag = etree.QName(el).localname
        f = lambda n, d='0': float(el.get(n, d))
        if tag == 'path':
            return '<PathGeometry FillRule="Nonzero" Figures=%s/>' % quoteattr(normalize_path(el.get('d'))), None
        if tag == 'rect':
            rx = el.get('rx'); ry = el.get('ry', rx)
            rad = '' if rx is None else ' RadiusX="%s" RadiusY="%s"' % (fmt(float(rx)), fmt(float(ry)))
            return '<RectangleGeometry Rect="%s,%s,%s,%s"%s/>' % (fmt(f('x')), fmt(f('y')), fmt(f('width')), fmt(f('height')), rad), None
        if tag == 'circle':
            return '<EllipseGeometry Center="%s,%s" RadiusX="%s" RadiusY="%s"/>' % (fmt(f('cx')), fmt(f('cy')), fmt(f('r')), fmt(f('r'))), None
        if tag == 'ellipse':
            return '<EllipseGeometry Center="%s,%s" RadiusX="%s" RadiusY="%s"/>' % (fmt(f('cx')), fmt(f('cy')), fmt(f('rx')), fmt(f('ry'))), None
        if tag == 'text':
            size = float(el.get('font-size', style.get('font-size', '16')))
            return '<PathGeometry FillRule="Nonzero" Figures=%s/>' % quoteattr(self.glyphs.path(el.text or '', f('x'), f('y'), size, el.get('text-anchor', 'start'))), None
        raise ValueError('element ' + tag)

    def clip_geometry(self, ref):
        cid = re.match(r'url\(#([^)]+)\)', ref).group(1)
        cp = self.clips[cid]
        geos = []
        for ch in cp:
            if not isinstance(ch.tag, str):
                continue
            g, _ = self.geometry(ch, {})
            t = ch.get('transform')
            if t:
                g = g.replace('/>', '><%s.Transform><MatrixTransform Matrix="%s"/></%s.Transform></%s>' % (
                    g[1:g.index(' ')], matrix_xaml(parse_transform(t)), g[1:g.index(' ')], g[1:g.index(' ')]), 1)
            geos.append(g)
        if len(geos) == 1:
            return geos[0]
        return '<GeometryGroup FillRule="Nonzero">' + ''.join(geos) + '</GeometryGroup>'

    INHERIT = ('fill', 'fill-opacity', 'stroke', 'stroke-opacity', 'stroke-width', 'stroke-linecap', 'stroke-linejoin', 'font-size')

    def node(self, el, style):
        if not isinstance(el.tag, str):
            return ''
        tag = etree.QName(el).localname
        if tag in ('defs', 'clipPath', 'linearGradient', 'radialGradient', 'title', 'desc'):
            return ''
        style = dict(style)
        for a in self.INHERIT:
            if el.get(a) is not None:
                style[a] = el.get(a)
        transform = el.get('transform')
        opacity = float(el.get('opacity', '1'))
        clip = el.get('clip-path')
        if tag == 'svg':  # nested svg: viewport + viewBox
            x, y = float(el.get('x', '0')), float(el.get('y', '0'))
            w, h = float(el.get('width')), float(el.get('height'))
            vb = [float(v) for v in re.split(r'[\s,]+', el.get('viewBox').strip())]
            s = min(w / vb[2], h / vb[3])
            tx = x + (w - vb[2] * s) / 2 - vb[0] * s
            ty = y + (h - vb[3] * s) / 2 - vb[1] * s
            inner = ''.join(self.node(c, style) for c in el)
            clipx = '<DrawingGroup.ClipGeometry><RectangleGeometry Rect="%s,%s,%s,%s"/></DrawingGroup.ClipGeometry>' % tuple(fmt(v) for v in vb)
            return '<DrawingGroup><DrawingGroup.Transform><MatrixTransform Matrix="%s"/></DrawingGroup.Transform>%s%s</DrawingGroup>' % (
                matrix_xaml((s, 0, 0, s, tx, ty)), clipx, inner)
        if tag == 'g':
            inner = ''.join(self.node(c, style) for c in el)
        else:
            inner = self.shape(el, style)
        if transform or opacity != 1 or clip:
            attrs = '' if opacity == 1 else ' Opacity="%s"' % fmt(opacity)
            parts = ''
            if transform:
                parts += '<DrawingGroup.Transform><MatrixTransform Matrix="%s"/></DrawingGroup.Transform>' % matrix_xaml(parse_transform(transform))
            if clip:
                parts += '<DrawingGroup.ClipGeometry>%s</DrawingGroup.ClipGeometry>' % self.clip_geometry(clip)
            return '<DrawingGroup%s>%s%s</DrawingGroup>' % (attrs, parts, inner)
        return inner

    def shape(self, el, style):
        geo, _ = self.geometry(el, style)
        fill = style.get('fill', '#000')
        fill_op = float(style.get('fill-opacity', '1'))
        stroke = style.get('stroke')
        stroke_op = float(style.get('stroke-opacity', '1'))
        out = ''
        fb = self.paint(fill, fill_op)
        pen = ''
        if stroke and stroke != 'none':
            pb = self.paint(stroke, stroke_op)
            if pb:
                caps = ''
                if style.get('stroke-linecap') == 'round':
                    caps += ' StartLineCap="Round" EndLineCap="Round"'
                if style.get('stroke-linejoin') == 'round':
                    caps += ' LineJoin="Round"'
                pen = '<GeometryDrawing.Pen><Pen Brush="%s" Thickness="%s" MiterLimit="4"%s/></GeometryDrawing.Pen>' % (
                    pb, fmt(float(style.get('stroke-width', '1'))), caps)
        if fb is None and not pen:
            return ''
        battr = '' if fb is None else ' Brush="%s"' % fb
        return '<GeometryDrawing%s><GeometryDrawing.Geometry>%s</GeometryDrawing.Geometry>%s</GeometryDrawing>' % (battr, geo, pen)

    def convert(self, path):
        root = etree.parse(path).getroot()
        self.collect_defs(root)
        vb = [float(v) for v in re.split(r'[\s,]+', root.get('viewBox').strip())]
        body = ''.join(self.node(c, {}) for c in root)
        frame = '%s,%s,%s,%s' % tuple(fmt(v) for v in vb)
        drawing = ('<DrawingImage x:Key=%s po:Freeze="True"><DrawingImage.Drawing><DrawingGroup>'
                   '<DrawingGroup.ClipGeometry><RectangleGeometry Rect="%s"/></DrawingGroup.ClipGeometry>'
                   '<GeometryDrawing Brush="#00000000"><GeometryDrawing.Geometry><RectangleGeometry Rect="%s"/></GeometryDrawing.Geometry></GeometryDrawing>'
                   '%s</DrawingGroup></DrawingImage.Drawing></DrawingImage>') % (quoteattr(self.key), frame, frame, body)
        return self.brush_xaml, drawing

HEADER = ('<!-- GENERATED by tools/art/svg2xaml.py from the design\'s drawings (docs/design/svg). Do not edit by hand. -->\n'
          '<ResourceDictionary xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"\n'
          '                    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"\n'
          '                    xmlns:po="http://schemas.microsoft.com/winfx/2006/xaml/presentation/options"\n'
          '                    xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006"\n'
          '                    mc:Ignorable="po">\n')

def write_dict(out_path, items, glyphs):
    lines = [HEADER]
    for key, svg in items:
        brushes, drawing = Conv(key, glyphs).convert(svg)
        lines.extend('  ' + b + '\n' for b in brushes)
        lines.append('  ' + drawing + '\n')
    lines.append('</ResourceDictionary>\n')
    with open(out_path, 'w', encoding='utf-8') as f:
        f.write(''.join(lines))
    return os.path.getsize(out_path)

def main():
    svg_dir, font, out = sys.argv[1:4]
    os.makedirs(out, exist_ok=True)
    glyphs = Glyphs(font)
    S = lambda n: os.path.join(svg_dir, n + '.svg')
    total = 0
    for theme in ('light', 'dark'):
        for fam in ('short', 'long', 'pro', 'generic'):
            items = [('scene.' + p, S('scene.%s.%s.%s' % (fam, p, theme))) for p in ('cc', 'co', 'oc', 'oo')]
            items += [('bud.' + s, S('bud.%s.%s.%s' % (fam, s, theme))) for s in ('l', 'r')]
            total += write_dict(os.path.join(out, 'Art.%s.%s.xaml' % (fam, theme)), items, glyphs)
        total += write_dict(os.path.join(out, 'Art.max.%s.xaml' % theme), [('max', S('max.' + theme))], glyphs)
    leds = [('led.%s.%s' % (f, k), S('led.%s.%s' % (f, k))) for f in ('short', 'long', 'pro') for k in ('g', 'a')]
    total += write_dict(os.path.join(out, 'Art.leds.xaml'), leds, glyphs)
    total += write_dict(os.path.join(out, 'Art.appicon.xaml'), [('appicon', S('appicon'))], glyphs)
    print('XAML written: %d KB' % (total // 1024))

if __name__ == '__main__':
    main()
